WiFi.mode(WIFI_AP);
WiFi.softAP("{{ap_ssid}}");
DNSServer dns; dns.start(53, "*", WiFi.softAPIP());
AsyncWebServer server(80);
server.on("/", HTTP_GET, [](AsyncWebServerRequest *r){
    r->send(200, "text/html", "<form action=/save><input name=ssid><input name=pw><button>Save</button></form>");
});
server.on("/save", HTTP_GET, [](AsyncWebServerRequest *r){
    Preferences p; p.begin("wifi");
    p.putString("ssid", r->getParam("ssid")->value());
    p.putString("pw", r->getParam("pw")->value());
    r->send(200, "text/plain", "saved, rebooting");
    delay(1000); ESP.restart();
});
server.begin();
